// LoadFolloweeUser loads the follower's FolloweeUser into the .R struct
func (o *Follower) LoadFolloweeUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.FolloweeUser = nil
	o.R.Loaded.FolloweeUser = false

	related, err := o.FolloweeUser(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R.FolloweeUser = related
	o.R.Loaded.FolloweeUser = true
	return nil
}

// LoadFolloweeUser loads the follower's FolloweeUser into the .R struct
func (os FollowerSlice) LoadFolloweeUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	users, err := os.FolloweeUser(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.FolloweeUser = nil
		o.R.Loaded.FolloweeUser = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	followerByKey := make(map[uuid.UUID][]*Follower, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		followerByKey[o.FolloweeID] = append(followerByKey[o.FolloweeID], o)
	}

	for _, rel := range users {

		owners, ok := followerByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.FolloweeUser != nil {
				continue
			}

			o.R.FolloweeUser = rel

		}
	}

	return nil
}

