type followerJoins[Q dialect.Joinable] struct {
	typ          string
	FolloweeUser modAs[Q, userColumns]
	FollowerUser modAs[Q, userColumns]
}

func (j followerJoins[Q]) aliasedAs(alias string) followerJoins[Q] {
	return buildFollowerJoins[Q](buildFollowerColumns(alias), j.typ)
}

func buildFollowerJoins[Q dialect.Joinable](cols followerColumns, typ string) followerJoins[Q] {
	return followerJoins[Q]{
		typ: typ,
		FolloweeUser: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.FolloweeID),
					))
				}

				return mods
			},
		},
		FollowerUser: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.FollowerID),
					))
				}

				return mods
			},
		},
	}
}
